/**
 * `evals rebase-refresh <proposalId>` — the CLI wiring `refreshBeforeSha`'s
 * own docstring (server/services/reviews/apply.ts) points to: the ONLY
 * legitimate way to unstick a proposal permanently wedged in `rebase_needed`
 * by the §11 #17 guard (beforeSha vs the target's real HEAD). Meant to be run
 * AFTER a human has confirmed the proposal's branch is still valid despite
 * the divergence (the chip a `rebase_needed` outcome opens spells this out) —
 * this command itself does not ask for that confirmation, it only performs
 * the mechanical resolve-then-advance once a human has decided to run it.
 *
 * Resolves the new beforeSha via `resolveCurrentMainSha` (the real,
 * currently-fetched HEAD of the target's `main` — same git primitives
 * `applyProposal`'s own §11 #17 check uses, reused rather than duplicated),
 * then calls the already-exported `refreshBeforeSha(proposalId, newBeforeSha)`
 * — no proposal-mutation logic lives in this CLI file, same thin-wrapper
 * pattern as `cmdApply`/`cmdRevert` above.
 */
async function cmdRebaseRefresh(proposalId: string) {
  const ctx = applyContextFromEnv();

  const before = await getImprovementProposal(proposalId);
  if (!before) fail(`ImprovementProposal introuvable : ${proposalId}`);
  const previousBeforeSha = before.beforeSha;

  const newBeforeSha = await resolveCurrentMainSha(proposalId, ctx);
  const updated = await refreshBeforeSha(proposalId, newBeforeSha);

  process.stdout.write(
    `VERDICT: REBASE_REFRESHED\n` +
      `Proposal ${updated.id}\n` +
      `Ancien beforeSha : ${previousBeforeSha}\n` +
      `Nouveau beforeSha : ${updated.beforeSha}\n` +
      `Prochaine étape : cd ~/Desktop/my-projets/workstation && bun run evals apply ${updated.id}\n`,
  );
}

